package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaThDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("อัลลอฮุมมา บิกา อัสบะนะฮฺ", "โอ้อัลลอฮ์ โดยพระองค์เราจึงเข้าสู่ยามเช้า และโดยพระองค์เราจึงเข้าสู่ยามเย็น เรามีชีวิตอยู่โดยพระองค์ และโดยพระองค์เราตาย และการฟื้นคืนพระชนม์เป็นของพระองค์", "ในตอนเช้า.", "ศาสดาพยากรณ์ ﷺ สอนสหายให้พูดเช้านี้และเย็น"),
        "dua_allahumma_bika_amsayna" to DuaText("อัลลอฮุมมา บิกา อัมสัยนะ", "โอ้อัลลอฮ์ ข้าพระองค์เข้าสู่เวลาเย็นโดยพระองค์ และข้าพระองค์เข้าสู่เวลาเช้าโดยพระองค์ เรามีชีวิตอยู่โดยคุณ และโดยคุณเราตาย และกลับมาหาคุณ", "ในตอนเย็น.", "ศาสดาพยากรณ์ ﷺ สอนสหายให้พูดเช้านี้และเย็น"),
        "dua_afiyah_morning" to DuaText("การขออาฟิยะห์", "โอ้อัลลอฮ์ ฉันขอการอภัยโทษและความอยู่ดีมีสุขจากพระองค์ทั้งในโลกนี้และปรโลก", "พระศาสดา ﷺ ไม่เคยละทิ้งดุอานี้เช้าหรือเย็น", "ไม่มีใครได้รับอะไรที่ดีไปกว่าความเป็นอยู่ที่ดี"),
        "dua_afini_fi_badani" to DuaText("สุขภาพร่างกาย การได้ยิน และการมองเห็น", "โอ้อัลลอฮ์ โปรดประทานความเป็นอยู่ที่ดีแก่ร่างกายของฉัน โอ้อัลลอฮ์ โปรดประทานความเป็นอยู่ที่ดีแก่การได้ยินของฉัน โอ้อัลลอฮ์ โปรดประทานความอยู่ดีมีสุขแก่สายตาของฉันด้วย ไม่มีพระเจ้าอื่นใดนอกจากพระองค์", "สามครั้งทุกเช้าและเย็น", "ดุอาเพื่อสุขภาพและการปกป้องประสาทสัมผัส"),
        "dua_ya_hayyu_aslih" to DuaText("แก้ไขกิจการของฉันทั้งหมด", "ข้าแต่ผู้เป็นนิรันดร์ ข้าแต่ผู้ค้ำจุน ด้วยความเมตตาของพระองค์ ข้าพระองค์ขอความช่วยเหลือ จงจัดการเรื่องต่างๆ ของข้าพระองค์ให้เรียบร้อย และอย่าทิ้งข้าพระองค์ไว้กับตัวเองแม้แต่ชั่วพริบตา", "ศาสดาหมายเลข ﷺ แนะนำให้ฟาติมะห์ (RA) พูดตอนเช้าและเย็น", "ขอความช่วยเหลือจากอัลลอฮ์ในทุกเรื่อง"),
        "dua_subhanallah_adada_khalqihi" to DuaText("ตัสบีห์ แห่งญุวัยริยะฮ์ (RA)", "มหาบริสุทธิ์แห่งอัลลอฮ์และการสรรเสริญทั้งมวลเป็นของพระองค์ มากเท่าที่พระองค์ทรงสร้าง มากเท่าที่พระองค์ทรงประสงค์ เท่ากับน้ำหนักของบัลลังก์ของพระองค์และหมึกแห่งวจนะของพระองค์", "สามครั้งในตอนเช้า - หนักกว่าชั่วโมงดิกิร์", "การพูดสี่วลีนี้สามครั้งมีค่ามากกว่าซิกิรตั้งแต่เช้าจรดค่ำ"),
        "dua_salawat" to DuaText("ดูรูด-อี-อิบราฮิมี", "โอ้อัลลอฮ์ โปรดส่งคำอธิษฐานไปยังมูฮัมหมัด ﷺ และครอบครัวของมูฮัมหมัด เช่นเดียวกับที่พระองค์ทรงส่งคำอธิษฐานไปยังอิบราฮิม (AS) และครอบครัวของอิบราฮิม คุณเป็นผู้ที่น่ายกย่องและรุ่งโรจน์ โอ้อัลลอฮ์ โปรดอวยพรมูฮัมหมัด ﷺ และครอบครัวของมูฮัมหมัด เช่นเดียวกับที่พระองค์ทรงอวยพรอิบราฮิม (AS) และครอบครัวของอิบราฮิม คุณเป็นผู้ที่น่ายกย่องและรุ่งโรจน์", "Salawat แก่พระศาสดา ﷺ ในการอธิษฐานและตลอดเวลา", "ผู้ใดละหมาดหนึ่งครั้ง อัลลอฮ์จะทรงประทานความเมตตาสิบประการแก่เขา (มุสลิม 408)"),
        "dua_wudu_after" to DuaText("หลังจากวูดู", "ฉันเป็นพยานว่าไม่มีผู้ใดมีสิทธิที่จะได้รับการสักการะนอกจากอัลลอฮ์ ผู้เดียว โดยไม่มีภาคีใด ๆ และมูฮัมหมัด ﷺ เป็นผู้รับใช้และศาสนทูตของพระองค์ โอ้อัลลอฮ์ โปรดให้ฉันอยู่ในหมู่ผู้สำนึกผิดและบรรดาผู้ขัดเกลาตนเอง", "หลังจากเสร็จสิ้นการละหมาด", "ประตูสวรรค์ทั้งแปดบานเปิดเพื่อให้เขาเข้าไปได้ตามต้องการ"),
        "dua_wudu_before" to DuaText("ก่อนวูดู", "ในนามของอัลลอฮ.", "เมื่อเริ่มละหมาด", "ไม่มีวูดู (สมบูรณ์) สำหรับผู้ที่ไม่ได้เอ่ยถึงพระนามของอัลลอฮ์เหนือมัน"),
        "dua_istiftah" to DuaText("เปิดคำวิงวอน (สะนะ)", "มหาบริสุทธิ์แด่พระองค์ ข้าแต่อัลลอฮ์ และการสรรเสริญเป็นของพระองค์ พระนามของพระองค์เป็นสุข พระบารมีของพระองค์เป็นที่ยกย่อง และไม่มีพระเจ้าอื่นใดนอกจากพระองค์", "ในช่วงเริ่มต้นของการละหมาด หลังจากตักบีรเปิด", "ดุอาอฺเปิดการอธิษฐานของซุนนะฮฺ"),
        "dua_ruku" to DuaText("ในรูกุ", "มหาบริสุทธิ์แด่พระเจ้าของฉันผู้ทรงยิ่งใหญ่", "อย่างน้อยสามครั้งใน ruku", "ซุนนะฮ tasbih ของ ruku"),
        "dua_sujood" to DuaText("ในซูจูด", "มหาบริสุทธิ์แด่พระเจ้าของฉันผู้สูงสุด", "อย่างน้อยสามครั้งในซูจูด", "คนรับใช้นั้นใกล้ชิดกับพระเจ้าของเขามากที่สุดในขณะที่สุญูด (มุสลิม 482)"),
        "dua_rising_ruku" to DuaText("ขึ้นมาจาก Ruku", "อัลลอฮ์ทรงได้ยินผู้ที่สรรเสริญพระองค์ พระเจ้าของเรา บรรดาการสรรเสริญเป็นของพระองค์", "ขณะลุกขึ้นจากรุกุและยืนตัวตรง", "ใครก็ตามที่ 'รอบบะนะ วะ ลากัลฮัมด์' ตรงกับของเหล่ามะลาอิกะฮ์ ความผิดบาปในอดีตของเขาจะได้รับการอภัย"),
        "dua_between_sajdas" to DuaText("ระหว่างสองสัจดาส", "พระเจ้าของข้าพเจ้า ขอทรงอภัยโทษข้าพเจ้าด้วย พระเจ้าของข้าพเจ้า ขอทรงอภัยโทษข้าพเจ้าด้วย", "ขณะนั่งอยู่ระหว่างสุญูดทั้งสอง", "ซุนนะฮฺ dua ของการนั่งระหว่างสุญูด"),
        "dua_before_salam_four" to DuaText("ให้พ้นจากสี่สิ่ง (ก่อนสลาม)", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากการลงโทษในนรก จากการลงโทษในหลุมศพ จากการทดสอบแห่งชีวิตและความตาย และจากความชั่วร้ายของการทดลองของอัลลอฮฺ (ดัจญาล)", "หลังจากตะชะหุดและละหมาดครั้งสุดท้าย ก่อนสลาม", "ศาสดาพยากรณ์ ﷺ ทรงบัญชาให้แสวงหาที่หลบภัยจากสี่สิ่งนี้"),
        "dua_qunoot_witr" to DuaText("กุนูตในวิฏร", "โอ้อัลลอฮ์ ขอทรงชี้นำฉันในหมู่ผู้ที่พระองค์ทรงแนะนำ โปรดประทานความอยู่ดีมีสุขแก่ฉันในหมู่ผู้ที่พระองค์ทรงประทานความอยู่ดีมีสุข โปรดนำข้าพระองค์ไปอยู่ในความดูแลของพระองค์ ในหมู่ผู้ที่พระองค์ทรงดูแล โปรดอวยพรฉันในสิ่งที่พระองค์ทรงประทาน และปกป้องฉันจากความชั่วร้ายของสิ่งที่พระองค์ทรงกำหนดไว้ คุณออกคำสั่งและไม่มีใครออกกฤษฎีกาต่อคุณ และคนที่คุณเป็นเพื่อนจะไม่ถูกทำให้อับอาย สรรเสริญและสูงส่งแด่พระเจ้าของเรา", "ในคำอธิษฐานวิทร — พระศาสดา ﷺ สอนเรื่องนี้แก่ฮะซัน อิบนุ อาลี (RA)", "ซุนนะฮฺ qunoot ของวิทร (ในบรรดาฮานาฟิส 'อัลลอฮุมมา อินนา นัสตาอินูกา' ก็เป็นที่รู้จักกันดีเช่นกัน)"),
        "dua_qunoot_hanafi" to DuaText("กุนุต (อัลลอฮุมมา อินนา นะสตาอินูกา)", "โอ้อัลลอฮ์ เราขอความช่วยเหลือจากพระองค์และการอภัยโทษจากพระองค์ เราศรัทธาต่อพระองค์และพึ่งพาพระองค์ เราสรรเสริญพระองค์อย่างดีที่สุด เราขอบคุณพระองค์ และไม่เนรคุณ และเราละทิ้งผู้ใดก็ตามที่ฝ่าฝืนพระองค์ โอ้ อัลลอฮ์ พระองค์ผู้เดียวที่เราเคารพสักการะ เราขอวิงวอนและสุญูดต่อพระองค์ เราเร่งรีบและต่อสู้ดิ้นรนต่อพระองค์ เราหวังในความเมตตาของพระองค์ และเกรงกลัวการลงโทษของพระองค์ แท้จริงการลงโทษของพระองค์ก็จะไปถึงบรรดาผู้ปฏิเสธศรัทธา", "ในวิทร์ — การปฏิบัติของฮานาฟิส", "รายงานจากอุมัร (RA) ในกูนุต."),
        "dua_sleep_aslamtu" to DuaText("ประโยคสุดท้ายก่อนนอน", "โอ้อัลลอฮ์ ฉันขอมอบตัวฉันต่อพระองค์ และฝากเรื่องของฉันไว้กับพระองค์ และฉันขอมอบความคุ้มครองจากพระองค์ ด้วยความหวังในตัวพระองค์ และความกลัวต่อพระองค์ ไม่มีที่พึ่งและไม่มีทางหนีจากพระองค์ได้นอกจากพระองค์ ฉันศรัทธาในคัมภีร์ของคุณซึ่งคุณเปิดเผยและศาสดาของคุณที่คุณส่งมา", "หลังละหมาด ให้นอนตะแคงขวา เป็นคำสุดท้ายก่อนเข้านอน", "หากเขาเสียชีวิตในคืนนั้น เขาก็ตายตามฟิตเราะห์ (อิสลาม)"),
        "dua_waking_night" to DuaText("ตื่นขึ้นในเวลากลางคืน", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจนั้นเป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง การสรรเสริญทั้งมวลเป็นของอัลลอฮ์ มหาบริสุทธิ์แด่อัลลอฮ์ ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ อัลลอฮ์คือผู้ทรงยิ่งใหญ่ และไม่มีอำนาจหรืออำนาจใด ๆ เว้นแต่กับอัลลอฮ์ โอ้อัลลอฮ์ โปรดอภัยโทษให้ฉันด้วย", "เมื่อตื่นขึ้นในตอนกลางคืน", "ดุอาของเขาได้รับคำตอบ และหากเขาทำวูดูและละหมาด คำอธิษฐานของเขาก็เป็นที่ยอมรับ"),
        "dua_hamm_ibn_masud" to DuaText("ดุอาอฺเพื่อความเศร้าโศก (อิบนุ มัสอูด)", "โอ้ อัลลอฮ์ ข้าพระองค์เป็นผู้รับใช้ของพระองค์ บุตรของผู้รับใช้ของพระองค์ บุตรของสาวใช้ของพระองค์ ขมับของข้าพระองค์อยู่ในพระหัตถ์ของพระองค์ พระบัญชาของพระองค์เหนือข้าพระองค์สำเร็จแล้ว และกฤษฎีกาของพระองค์เกี่ยวกับข้าพระองค์นั้นยุติธรรม ฉันถามคุณด้วยทุกชื่อที่เป็นของคุณ ซึ่งคุณตั้งชื่อตัวเอง หรือเปิดเผยไว้ในหนังสือของคุณ หรือสอนให้กับสิ่งสร้างของคุณ หรือเก็บไว้กับตัวคุณเองในความรู้ในสิ่งที่มองไม่เห็น — ว่าพระองค์ทรงทำให้อัลกุรอานเป็นน้ำพุในใจของฉัน เป็นแสงสว่างในอกของฉัน การขจัดความเศร้าโศกของฉัน และการจากไปของความกังวลของฉัน", "ในความโศกเศร้าและความทุกข์ — อัลลอฮ์ทรงแทนที่ความเศร้าโศกด้วยความยินดี", "อัลลอฮ์ทรงขจัดความกังวลและความเศร้าโศกของเขา และทรงประทานความปิติยินดีแก่เขาแทน"),
        "dua_difficulty_sahl" to DuaText("เมื่อมีสิ่งที่ยากลำบาก", "โอ้อัลลอฮฺ ไม่มีสิ่งใดที่ง่ายนอกจากสิ่งที่พระองค์ทรงทำให้ง่าย และพระองค์ทรงทำให้สิ่งที่ยากเป็นเรื่องง่าย หากท่านปรารถนา", "เมื่อบางสิ่งบางอย่างรู้สึกว่ายาก", "ความง่ายดายในการสอบและงานที่ยากลำบาก"),
        "dua_musibah" to DuaText("เมื่อเกิดภัยพิบัติ (อิสติรญา)", "เราเป็นสิทธิของอัลลอฮ์และเราจะต้องกลับคืนสู่พระองค์ โอ้อัลลอฮ์ โปรดตอบแทนฉันในความทุกข์ยากของฉัน และโปรดทดแทนให้ฉันด้วยสิ่งที่ดีกว่านี้", "เมื่อมีการสูญเสียหรือภัยพิบัติใดๆ", "อัลลอฮฺทรงประทานสิ่งที่ดีกว่าอย่างแน่นอน — อุมม์ ซาลามะห์ (RA) ได้รับท่านศาสดา ﷺ"),
        "dua_debt" to DuaText("เพื่อการปลดหนี้", "โอ้อัลลอฮ์ โปรดให้ฉันพอแล้วกับสิ่งที่พระองค์ได้ทรงบัญญัติให้ต่อต้านสิ่งที่พระองค์ได้ทรงประทานให้เป็นสิ่งผิดกฎหมาย และด้วยความโปรดปรานของพระองค์ โปรดทำให้ฉันเป็นอิสระจากทุกสิ่งนอกเหนือจากพระองค์", "เพื่อการชำระหนี้ — สอนโดยอาลี (RA)", "แม้ว่าหนี้จะเหมือนภูเขา อัลลอฮ์จะทรงชำระหนี้นั้น"),
        "dua_anger" to DuaText("เมื่อโกรธ", "ฉันขอความคุ้มครองต่ออัลลอฮ์ให้พ้นจากชัยฏอนผู้ถูกสาปแช่ง", "เมื่อโกรธ.", "พระศาสดา ﷺ กล่าวว่า: หากเขาพูดเช่นนี้ ความโกรธของเขาจะหายไป"),
        "dua_waswasa" to DuaText("ต่อต้าน Waswasa ด้วยความศรัทธา", "ฉันศรัทธาในอัลลอฮ์และศาสนทูตของพระองค์", "เมื่อซาตานกระซิบเรื่องศรัทธามา", "เมื่อเสียงกระซิบดังขึ้น ให้พูดสิ่งนี้และหยุดอยู่แค่นั้น (และขอความคุ้มครองต่ออัลลอฮฺด้วย)"),
        "dua_travel_full" to DuaText("วิงวอนการเดินทางที่สมบูรณ์", "โอ้อัลลอฮ์ เราขอพระองค์ในการเดินทางครั้งนี้เพื่อความชอบธรรมและความยำเกรง และการกระทำที่พอพระทัยพระองค์ โอ้อัลลอฮ์ โปรดทำให้การเดินทางครั้งนี้เป็นเรื่องง่ายสำหรับเรา และลดระยะทางให้สั้นลง โอ้อัลลอฮ์ พระองค์ทรงเป็นผู้ร่วมเดินทางและเป็นผู้พิทักษ์ครอบครัว", "เมื่อออกเดินทางหลังจาก", "ดุอาการเดินทางซุนนะฮฺที่สมบูรณ์"),
        "dua_return_travel" to DuaText("กลับจากท่องเที่ยว", "เรากำลังกลับมา กลับใจ นมัสการและสรรเสริญพระเจ้าของเรา", "เมื่อกลับจากการเดินทาง", "พระศาสดา ﷺ กล่าวสิ่งนี้เมื่อกลับจากการเดินทาง"),
        "dua_farewell_traveller" to DuaText("กล่าวคำอำลากับนักเดินทาง", "ฉันขอมอบศาสนาของคุณต่ออัลลอฮ์ ความไว้วางใจของคุณ และผลลัพธ์ของการกระทำของคุณ", "เมื่อกล่าวคำอำลากับนักเดินทาง", "สิ่งที่มอบหมายต่ออัลลอฮ์จะไม่มีวันสูญหาย"),
        "dua_entering_town" to DuaText("หยุดที่สถานที่", "ฉันขอความคุ้มครองด้วยพระวจนะอันสมบูรณ์แบบของอัลลอฮ์จากความชั่วร้ายของทุกสิ่งที่พระองค์ทรงสร้าง", "เมื่อแวะที่สถานที่หรือมาถึงเมืองใหม่", "ไม่มีสิ่งใดจะทำร้ายเขาได้จนกว่าเขาจะจากที่นั่น"),
        "dua_boarding_ship" to DuaText("การขึ้นเรือ/ยานพาหนะ", "ด้วยพระนามของอัลลอฮ์คือการแล่นและการทอดสมอของมัน แท้จริงพระเจ้าของฉันเป็นผู้ทรงอภัยโทษ ผู้ทรงเมตตาเสมอ", "เมื่อขึ้นเรือหรือยานพาหนะ — คำพูดของศาสดานูห์ (AS)", "โองการอัลกุรอาน — ดุอาแห่งเรือ (AS) ของนูห์"),
        "dua_istighfar_hayyul_qayyum" to DuaText("อิสติฆฟารกับฮายูลก็อยุม", "ฉันขออภัยโทษจากอัลลอฮ์ เว้นแต่พระองค์ไม่มีพระเจ้าอื่นใด ผู้ทรงดำรงอยู่ ผู้ทรงดำรงอยู่ และฉันขอกลับใจต่อพระองค์", "สำหรับการกลับใจ", "บาปของเขาได้รับการอภัยแล้วแม้ว่าเขาจะหนีออกจากสนามรบก็ตาม"),
        "dua_rabbighfir_warham" to DuaText("รับบีเฟอร์ วอร์แฮม", "ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงอภัยโทษและทรงเมตตาเถิด เพราะพระองค์ทรงเป็นผู้ดีที่สุดในบรรดาผู้แสดงความเมตตา", "ดุอาอัลกุรอาน — เพื่อการให้อภัยและความเมตตา", "โองการสุดท้ายของ Surah al-Mu'minun"),
        "dua_majlis_kaffarah" to DuaText("กัฟฟารัต อัล-มัจลิซ", "มหาบริสุทธิ์แด่พระองค์ ข้าแต่อัลลอฮ์ และการสรรเสริญเป็นของพระองค์ ข้าพเจ้าเป็นพยานว่าไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ฉันขอการอภัยโทษจากคุณและกลับมาหาคุณด้วยการกลับใจ", "เมื่อลุกขึ้นจากการชุมนุม", "มันจะกลายเป็นการชดใช้ความผิดใดๆ ก็ตามที่พูดในที่ประชุม"),
        "dua_jami_forgiveness" to DuaText("การให้อภัยที่ครอบคลุม", "โอ้อัลลอฮ์ โปรดอภัยให้กับฉันในความผิดพลาดของฉัน ความไม่รู้ของฉัน กิจการที่มากเกินไปของฉัน และทุกสิ่งที่พระองค์ทรงรู้ดียิ่งกว่าฉัน", "Dua ที่ครอบคลุมของศาสดา ﷺ", "พระศาสดา ﷺ เคยทำดุอานี้"),
        "dua_parents_nuh" to DuaText("Dua ของ Nuh (AS) สำหรับผู้ปกครอง", "ข้าแต่พระเจ้าของข้าพเจ้า โปรดอภัยโทษให้แก่ข้าพเจ้า บิดามารดาของข้าพเจ้า ผู้ใดที่เข้ามาในบ้านของข้าพเจ้าในฐานะผู้ศรัทธา และบรรดาผู้ศรัทธาและสตรีผู้ศรัทธาทุกคน", "เพื่อพ่อแม่และผู้ศรัทธา", "ดุอาของท่านศาสดานูห์ (AS)"),
        "dua_shukr_parents" to DuaText("ความกตัญญูต่อพ่อแม่และลูกหลานที่ชอบธรรม", "พระเจ้าของข้าพระองค์ โปรดช่วยให้ข้าพระองค์ซาบซึ้งต่อความโปรดปรานของพระองค์ที่พระองค์ทรงประทานแก่ข้าพระองค์และพ่อแม่ของข้าพระองค์ และทรงกระทำความดีที่พระองค์พอพระทัย และทำให้ลูกหลานของข้าพระองค์ชอบธรรม ฉันขอกลับใจต่อพระองค์ และฉันอยู่ในหมู่ผู้สวามิภักดิ์", "ดุอาอฺกุรอานมีอายุครบสี่สิบปี", "ความกตัญญู ความดี และความชอบธรรมของลูกๆ ทั้งหมดในดุอาเดียว"),
        "dua_intimacy" to DuaText("ก่อนความสัมพันธ์ฉันสามีภรรยา", "ในนามของอัลลอฮ. โอ้อัลลอฮ์ โปรดทรงให้ชัยฏอนอยู่ห่างจากพวกเรา และทรงให้ชัยฏอนอยู่ห่างจากสิ่งที่ (เด็กๆ) ที่พระองค์ประทานแก่เรา", "ก่อนความสัมพันธ์ในชีวิตสมรส", "หากเด็กถูกกำหนดไว้ ชัยฏอนจะไม่ทำร้ายเด็กคนนั้น"),
        "dua_ibrahim_children_protection" to DuaText("การคุ้มครองบ้านและเด็ก", "พระเจ้าของข้าพระองค์ โปรดทำให้เมืองนี้ปลอดภัย และปกป้องฉันและลูก ๆ ของฉันให้ห่างจากการสักการะรูปเคารพ", "ดุอาของท่านศาสดาอิบราฮิม (AS) — เพื่อความปลอดภัยของเมืองและลูกหลานของเขา", "ดุอาอ์เพื่อการยืนหยัดในการเตาฮีด"),
        "dua_drinking_milk" to DuaText("เมื่อดื่มนม", "โอ้อัลลอฮ์ โปรดประทานความจำเริญแก่เรา และโปรดประทานเพิ่มเติมแก่เราด้วย", "เมื่อดื่มนม", "นมเพียงพอสำหรับเป็นทั้งอาหารและเครื่องดื่ม"),
        "dua_iftar_host" to DuaText("เมื่อเลิกอดอาหารกับผู้อื่น", "ขอให้ผู้ถือศีลอดถือศีลอดร่วมกับคุณ ขอให้คนชอบธรรมกินอาหารของคุณ และขอให้เหล่าทูตสวรรค์อธิษฐานเพื่อคุณ", "เมื่อละศีลอดที่บ้านของใครบางคน", "ดุอาอ์ของท่านศาสดา ﷺ แก่เจ้าภาพ"),
    )
}
